update approval_m
set appr_stat = #{appr_stat}
    ,reject = #{reject}
    ,appr_admin = #{appr_admin}
where appr_no = #{appr_no}

update approval_m
set appr_admin = #{appr_admin}
where appr_no = #{appr_no}

update approval_d
set appr_tg = #{appr_tg}
    ,appr_date = now()
    ,appr_remarks = #{appr_remarks}
where appr_no = #{appr_no}
and appr_num = #{appr_num}
and d_seq = #{d_seq}

UPDATE approval_d
SET appr_remarks = #{appr_remarks}
WHERE appr_no = #{appr_no}
  AND d_seq = #{d_seq}
  AND appr_emp_no = #{appr_emp_no}

mapper.select:
SELECT a.appr_no ,a.emp_no ,a.user_nm ,a.proj_code ,a.proj_name ,a.address ,d.d_seq ,d.appr_num ,d.appr_emp_no ,d.appr_emp_nm ,d.appr_position ,d.first_appr_emp_nm ,d.first_appr_date ,d.next_appr_emp_nm ,d.next_appr_emp_no ,d.last_appr_emp_no ,d.last_appr_emp_nm ,d.last_appr_date ,d.appr_stat ,d.appr_admin ,d.all_appr_emp_nos ,d.view_role FROM ( SELECT a.appr_no, MAX(a.emp_no) AS emp_no , MAX(a.user_nm) AS user_nm , MAX(a.proj_code) AS proj_code , MAX(a.proj_name) AS proj_name , MAX(a.crtdate) AS crtdate , CONCAT(MAX(CONCAT(b.address,' ',b.address_d)),(CASE WHEN COUNT(*) > 1 THEN CONCAT(' 외 ',COUNT(*)-1,'건') ELSE '' END)) AS address FROM contract_m a JOIN contract_d b ON a.seq=b.seq AND a.appr_no IS NOT NULL GROUP BY a.appr_no ) a JOIN ( SELECT c.appr_no ,c.appr_stat ,c.appr_admin ,c.d_seq ,c.appr_num ,c.appr_emp_no ,c.appr_emp_nm ,c.appr_remarks ,c.appr_date ,c.appr_position ,c.last_tag ,c.appr_tg ,c.appr_group ,c.first_appr_emp_nm ,c.first_appr_date ,c.last_appr_emp_no ,c.last_appr_emp_nm ,c.last_appr_date ,c.next_appr_emp_nm ,c.next_appr_emp_no ,c.all_appr_emp_nos ,c.view_role FROM ( SELECT b.rnum ,b.appr_no ,b.appr_stat ,b.appr_admin ,b.d_seq ,b.appr_num ,b.appr_emp_no ,b.appr_emp_nm ,b.appr_remarks ,b.appr_date ,b.appr_position ,b.last_tag ,b.appr_tg ,b.appr_group ,b.first_appr_emp_nm ,b.first_appr_date ,MAX(CASE WHEN appr_num = last_appr_c_num AND appr_tg = 'T' THEN appr_emp_no ELSE '' END)OVER( PARTITION BY appr_no) AS last_appr_emp_no ,MAX(CASE WHEN appr_num = last_appr_c_num AND appr_tg = 'T' THEN appr_emp_nm ELSE '' END)OVER( PARTITION BY appr_no) AS last_appr_emp_nm ,MAX(CASE WHEN appr_num = last_appr_c_num AND appr_tg = 'T' THEN appr_date ELSE NULL END)OVER( PARTITION BY appr_no) AS last_appr_date ,(CASE WHEN appr_group = 'A' AND next_appr_emp_nm = '' THEN '업무지원팀' ELSE next_appr_emp_nm END) next_appr_emp_nm ,b.next_appr_emp_no ,emp_list.all_appr_emp_nos ,CASE WHEN EXISTS ( SELECT 1 FROM approval_cc cc WHERE cc.appr_no = b.appr_no AND cc.emp_no = #{emp_no} ) AND (emp_list.all_appr_emp_nos IS NULL OR FIND_IN_SET(#{emp_no}, emp_list.all_appr_emp_nos) = 0) THEN 'CC' ELSE 'APPROVER' END AS view_role FROM ( SELECT a1.appr_no, a1.appr_stat, a1.appr_admin , a2.d_seq, a2.appr_num, a2.appr_emp_no, a2.appr_emp_nm, a2.appr_remarks , (CASE WHEN appr_tg = 'T' THEN a2.appr_date ELSE NULL END) AS appr_date , a2.appr_position, a2.last_tag, IFNULL(a2.appr_tg,'N') AS appr_tg , a2.appr_group , LAG(a2.appr_emp_no,1,'')OVER(PARTITION BY a1.appr_no ORDER BY a2.appr_num DESC) AS next_appr_emp_no , LAG(a2.appr_emp_nm,1,'')OVER(PARTITION BY a1.appr_no ORDER BY a2.appr_num DESC) AS next_appr_emp_nm , MAX(CASE WHEN a2.appr_num = 0 THEN a2.appr_emp_nm ELSE '' END )OVER(PARTITION BY a1.appr_no) AS first_appr_emp_nm , MAX(CASE WHEN a2.appr_num = 0 THEN a2.appr_date ELSE NULL END )OVER(PARTITION BY a1.appr_no) AS first_appr_date , MAX(a2.appr_num)OVER(PARTITION BY a1.appr_no) AS last_appr_num , ROW_NUMBER()OVER(PARTITION BY a1.appr_no ORDER BY (case when appr_tg = 'T' then 999 ELSE a2.appr_num END) ASC ) AS rnum , MAX(CASE WHEN a2.appr_tg = 'T' THEN a2.appr_num ELSE 0 END )OVER(PARTITION BY a1.appr_no) AS last_appr_c_num FROM approval_m a1 JOIN approval_d a2 ON a1.appr_no = a2.appr_no ) b LEFT JOIN ( SELECT appr_no, GROUP_CONCAT(appr_emp_no ORDER BY appr_num SEPARATOR ',') AS all_appr_emp_nos FROM approval_d GROUP BY appr_no ) emp_list ON b.appr_no = emp_list.appr_no ) c WHERE c.rnum = 1 ) d ON a.appr_no = d.appr_no AND ( FIND_IN_SET(#{emp_no}, d.all_appr_emp_nos) > 0 OR EXISTS ( SELECT 1 FROM approval_cc cc WHERE cc.appr_no = d.appr_no AND cc.emp_no = #{emp_no} ) )
and a.proj_code = #{proj_code}
and d.appr_emp_no = #{emp_no} and d.appr_tg != 'T' and d.appr_stat not in ('3','4')
and d.appr_stat in ('0','1','2')
and d.appr_stat = #{conf_tag}

SELECT COUNT(*)
FROM approval_d ad
WHERE ad.appr_no = #{appr_no}
  AND ad.appr_emp_no = #{appr_emp_no}
  AND IFNULL(ad.appr_tg, 'N') = 'T'
  AND ad.appr_num = (SELECT MAX(appr_num) FROM approval_d WHERE appr_no = #{appr_no})

SELECT appr_emp_no FROM approval_d
WHERE appr_no = #{appr_no} AND appr_num = #{appr_num}
LIMIT 1

