SELECT GROUP_CONCAT(DISTINCT dcd.appr_no ORDER BY dcd.appr_no SEPARATOR ',') as appr_no_list, d.emp_no, d.user_nm, d.proj_name, d.proj_code, CONCAT( MAX(CONCAT(cd.address, ' ', cd.address_d)), (CASE WHEN COUNT(DISTINCT dcd.appr_no) > 1 THEN CONCAT(' 외 ', COUNT(DISTINCT dcd.appr_no)-1, '건') ELSE '' END) ) AS address, d.mst_seq, d.id as draft_id, d.created_date, d.cust_reg_attempted FROM draft d JOIN draft_contract_detail dcd ON d.id = dcd.draft_id JOIN contract_m c ON dcd.appr_no = c.appr_no JOIN contract_d cd ON c.seq = cd.seq JOIN approval_m am ON dcd.appr_no = am.appr_no WHERE am.appr_stat = 3 AND d.mst_seq IS NOT NULL AND d.mst_seq != '' AND (d.cust_reg_attempted IS NULL OR d.cust_reg_attempted != 'Y')
AND c.emp_no = #{user_no}
GROUP BY d.id, d.emp_no, d.user_nm, d.proj_code, d.proj_name, d.mst_seq, d.created_date, d.cust_reg_attempted ORDER BY d.created_date DESC

